    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Convert 4s in straight runs bordered by 9s on both ends, in rows or columns.
    for horizontal in (True, False):
        fixed_len = h if horizontal else w
        run_len = w if horizontal else h
        for fixed in range(fixed_len):
            vals = [grid[fixed][i] if horizontal else grid[i][fixed] for i in range(run_len)]
            i = 0
            while i < run_len:
                if vals[i] != 4:
                    i += 1
                    continue
                j = i
                while j < run_len and vals[j] == 4:
                    j += 1
                if i > 0 and j < run_len and vals[i-1] == 9 and vals[j] == 9:
                    for k in range(i, j):
                        if horizontal: out[fixed][k] = 2
                        else: out[k][fixed] = 2
                i = j
    return out
