 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Join consecutive pairs of marker-color 9s along rows/columns, painting
    # intervening background 4 cells with 2.
    for horizontal in (True, False):
        fixed_count = h if horizontal else w
        length = w if horizontal else h
        for fixed in range(fixed_count):
            line = [grid[fixed][i] if horizontal else grid[i][fixed] for i in range(length)]
            marks = [i for i, x in enumerate(line) if x == 9]
            for a, b in zip(marks, marks[1:]):
                for i in range(a + 1, b):
                    if line[i] == 4:
                        if horizontal: out[fixed][i] = 2
                        else: out[i][fixed] = 2
